WITH valid_subscriptions AS (SELECT * FROM subscriptions WHERE plan IN ('enterprise', 'premium', 'basic') AND plan IN ('standard', 'basic') AND status <> 'ACTIVE'), summary AS (SELECT plan, MAX(monthly_fee) - MIN(monthly_fee) AS monthly_fee_range FROM valid_subscriptions GROUP BY plan) SELECT plan, monthly_fee_range FROM summary WHERE monthly_fee_range >= 50 ORDER BY monthly_fee_range DESC, plan LIMIT 10
